1	package tariff
2	
3	import (
4		"errors"
5		"fmt"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	func ptrTime(t time.Time) *time.Time { return &t }
12	
13	// EffectiveVersionAt 场景的固定时间线（UTC，结束时刻均不含）：
14	//
15	//	旧版 seat-v1：单价 150 分，2026-03-01 00:00 起生效，登记结束 2026-03-31 00:00
16	//	新版 seat-v2：单价 180 分，2026-03-10 00:00 起替代旧版，2026-03-20 00:00 结束
17	//
18	// 查询时旧版的实际有效区间已被截断到 3 月 10 日：
19	// 3 月 9 日应选旧版，3 月 10 日应选新版，3 月 20 日两版都不生效且旧版不恢复。
20	var (
21		effV1Start = time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC)
22		effV1End   = time.Date(2026, 3, 31, 0, 0, 0, 0, time.UTC)
23		effV2Start = time.Date(2026, 3, 10, 0, 0, 0, 0, time.UTC)
24		effV2End   = time.Date(2026, 3, 20, 0, 0, 0, 0, time.UTC)
25	)
26	
27	func newEffectiveVersionBook(t *testing.T, start time.Time) (*Book, func(time.Time)) {
28		t.Helper()
29		now, setNow := fixedClock(start)
30		b := NewBook(WithClock(now))
31		v1End := effV1End
32		if err := b.RegisterVersion(RegisterRequest{
33			ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150,
34			Start: effV1Start, End: &v1End,
35		}); err != nil {
36			t.Fatalf("register seat-v1: %v", err)
37		}
38		v2End := effV2End
39		if err := b.RegisterVersion(RegisterRequest{
40			ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180,
41			Start: effV2Start, End: &v2End, Replaces: "seat-v1",
42		}); err != nil {
43			t.Fatalf("register seat-v2: %v", err)
44		}
45		return b, setNow
46	}
47	
48	// 题目示例：3 月 9 日返回旧版，3 月 10 日返回新版，
49	// 3 月 20 日明确表示当时没有生效版本，不能恢复旧版。
50	func TestEffectiveVersionAtHandoffExample(t *testing.T) {
51		b, _ := newEffectiveVersionBook(t, effV1Start)
52	
53		got, err := b.EffectiveVersionAt("seat", time.Date(2026, 3, 9, 0, 0, 0, 0, time.UTC))
54		if err != nil {
55			t.Fatalf("3 月 9 日旧版应生效: %v", err)
56		}
57		if got.VersionID != "seat-v1" || got.UnitPrice != 150 {
58			t.Fatalf("3 月 9 日选错版本: %+v", got)
59		}
60	
61		got, err = b.EffectiveVersionAt("seat", effV2Start)
62		if err != nil {
63			t.Fatalf("3 月 10 日新版应生效: %v", err)
64		}
65		if got.VersionID != "seat-v2" || got.UnitPrice != 180 {
66			t.Fatalf("3 月 10 日选错版本: %+v", got)
67		}
68	
69		_, err = b.EffectiveVersionAt("seat", effV2End)
